INSERT INTO system_announcements (id, created_by, title, body, priority) VALUES ('92000000-0000-0000-0000-00000000001', 'a0000000-0000-0000-0000-00000000001', 'NSE Market Holiday Notice', 'Trading on NSE/BSE will remain closed on 01-Nov-2024 on account of Diwali Laxmi Pujan. Muhurat trading session will be held from 18:00 to 19:00 IST.', 'URGENT');
INSERT INTO system_announcements (id, created_by, title, body, priority) VALUES ('92000000-0000-0000-0000-00000000002', 'a0000000-0000-0000-0000-00000000001', 'Annual KYC Compliance Mandate', 'SEBI guidelines mandate re-verification of Aadhaar-PAN linkage before 31-Dec-2024. Please update in your Profile.', 'NORMAL');
INSERT INTO system_announcements (id, created_by, title, body, priority) VALUES ('92000000-0000-0000-0000-00000000003', 'a0000000-0000-0000-0000-00000000001', 'Upgraded Risk Management Engine', 'PortfolioPro has enabled real-time Value at Risk (VaR 95%) and automated single-stock concentration warnings.', 'NORMAL');
INSERT INTO system_announcements (id, created_by, title, body, priority) VALUES ('92000000-0000-0000-0000-00000000004', 'a0000000-0000-0000-0000-00000000001', 'Scheduled System Maintenance', 'Platform server maintenance will be conducted on Saturday 14-Dec-2024 between 02:00 AM and 05:00 AM IST.', 'NORMAL');
INSERT INTO system_announcements (id, created_by, title, body, priority) VALUES ('92000000-0000-0000-0000-00000000005', 'a0000000-0000-0000-0000-00000000001', 'New Securities Listed', 'Tata Technologies and IREDA are now available for active trading and portfolio tracking.', 'NORMAL');
